import 'dart:convert';
import 'dart:typed_data';

/// The key decrypting a [PlayxSecureEnvData].
///
/// Generated files use [PlayxEnvKey.parts]: the key is split into two byte
/// lists XOR-ed at runtime, so it never appears as a contiguous value or a
/// string in the app.
class PlayxEnvKey {
  final List<int> _mask;
  final List<int> _masked;
  final String? _base64;

  /// A key split into [mask] and [masked], where key = mask XOR masked.
  const PlayxEnvKey.parts(List<int> mask, List<int> masked)
    : _mask = mask,
      _masked = masked,
      _base64 = null;

  /// A base64-encoded key, e.g. from `secure_env generate-key`.
  const PlayxEnvKey.base64(String value)
    : _mask = const [],
      _masked = const [],
      _base64 = value;

  /// The key bytes. Throws a [FormatException] if the key is malformed.
  Uint8List get bytes {
    final encoded = _base64;
    if (encoded != null) return base64Decode(encoded.trim());
    if (_mask.length != _masked.length) {
      throw const FormatException('Key parts have different lengths.');
    }
    return Uint8List.fromList([
      for (var i = 0; i < _mask.length; i++) _mask[i] ^ _masked[i],
    ]);
  }
}

/// Encrypted env values generated by the `secure_env` command:
/// `dart run playx:secure_env`, or `dart run playx_core:secure_env` when
/// depending on playx_core only.
///
/// Pass it to `PlayxEnvSettings.secureEnv`; [PlayxEnv] decrypts it at load
/// and serves the values through its getters.
class PlayxSecureEnvData {
  /// The format version of [data].
  final int version;

  /// The environment the values were generated for (`--env`), if any.
  final String? environment;

  /// The key, or `null` when it is passed with
  /// `--dart-define=PLAYX_ENV_KEY=<key>`.
  final PlayxEnvKey? key;

  /// The nonce followed by the AES-256-GCM encrypted values and tag.
  final List<int> data;

  const PlayxSecureEnvData({
    this.version = 1,
    this.environment,
    this.key,
    this.data = const [],
  });
}
